// STUDENT LIST (full — all forms)
// ============================================================
function getStudentListRaw() {
  const ss          = SpreadsheetApp.getActiveSpreadsheet();
  const allStudents = [];
  const seenAdmNo    = {}; // dedupe key: lower-cased AdmNo

  ['Form1','Form2','Form3','Form4'].forEach(function(formName) {
    const sheet = ss.getSheetByName(formName);
    if (!sheet) return;
    const data = sheet.getDataRange().getValues();
    if (data.length < 2) return;

    // Ensure header row has 'Status' in col 10 (index 9)
    // (safe no-op if it's already there)
    const headerRow = data[0];
    if (headerRow.length < 10 || !headerRow[9]) {
      sheet.getRange(1, 10).setValue('Status');
    }

    data.slice(1).forEach(function(r) {
      if (r[0] || r[1]) {
        var admNo = String(r[0] || '').trim();
        allStudents.push({
          admNo:     r[0],
          firstName: r[1],
          lastName:  r[2],
          sex:       r[3],
          dob:       r[4] ? r[4].toString().substring(0, 10) : '',
          className: r[5] || formName,
          parent:    r[6],
          phone:     r[7],
          address:   r[8],
          status:    r[9] ? r[9].toString().trim() : 'Pending'
        });
        if (admNo) seenAdmNo[admNo.toLowerCase()] = true;
      }
    });
  });

  // ------------------------------------------------------------
  // ALSO include students from the separate "Students" roster sheet.
  // That sheet is used elsewhere (attendance roster, deleteStudent)
  // but was previously ignored here, so any student who only exists
  // in "Students" (not yet in a Form1-4 sheet) could never be found
  // when linking a parent in "Manage Parents". Column names are read
  // dynamically so this works whatever order the columns are in.
  // ------------------------------------------------------------
  var rosterSh = ss.getSheetByName('Students');
  if (rosterSh && rosterSh.getLastRow() > 1) {
    var rv = rosterSh.getDataRange().getValues();
    var rh = rv.shift().map(function(h){ return String(h || '').trim(); });
    var iAdm    = rh.indexOf('AdmNo');
    var iFirst  = rh.indexOf('FirstName');
    var iLast   = rh.indexOf('LastName');
    var iName   = rh.indexOf('Name');
    var iSex    = rh.indexOf('Sex');
    var iDob    = rh.indexOf('DOB');
    var iCls    = rh.indexOf('Class');
    var iParent = rh.indexOf('Parent');
    var iPhone  = rh.indexOf('Phone');
    var iAddr   = rh.indexOf('Address');
    var iStat   = rh.indexOf('Status');

    rv.forEach(function(r) {
      var admNo = iAdm > -1 ? String(r[iAdm] || '').trim() : '';
      var firstName = '', lastName = '';
      if (iFirst > -1 || iLast > -1) {
        firstName = iFirst > -1 ? String(r[iFirst] || '').trim() : '';
        lastName  = iLast  > -1 ? String(r[iLast]  || '').trim() : '';
      } else if (iName > -1) {
        var parts = String(r[iName] || '').trim().split(/\s+/);
        firstName = parts.shift() || '';
        lastName  = parts.join(' ');
      }
      if (!admNo && !firstName) return;                          // nothing usable on this row
      if (admNo && seenAdmNo[admNo.toLowerCase()]) return;        // already have this student from a Form sheet

      allStudents.push({
        admNo:     admNo,
        firstName: firstName,
        lastName:  lastName,
        sex:       iSex   > -1 ? String(r[iSex]  || '').trim() : '',
        dob:       iDob   > -1 && r[iDob] ? r[iDob].toString().substring(0, 10) : '',
        className: iCls   > -1 ? String(r[iCls]  || '').trim() : '',
        parent:    iParent> -1 ? String(r[iParent]|| '').trim() : '',
        phone:     iPhone > -1 ? String(r[iPhone] || '').trim() : '',
        address:   iAddr  > -1 ? String(r[iAddr]  || '').trim() : '',
        status:    iStat  > -1 && r[iStat] ? String(r[iStat]).trim() : 'Approved'
      });
      if (admNo) seenAdmNo[admNo.toLowerCase()] = true;
    });
  }

  return allStudents;
}

function getStudentList() { return getStudentListRaw(); }

function generateUniqueAdmNo(ss){
  // AdmNo must be unique across ALL Form sheets (and the legacy Students sheet).
  // The format (prefix / separator / digits / first number) is set per school in Academic Settings.
  var f = acsAdmFormat_();
  if (!f.configured) throw new Error('Admission No. format is not set. Open Academic Settings > Admission No. and save it first.');
  var used = {};
  ['Form1','Form2','Form3','Form4','Students'].forEach(function(name){
    var sh = ss.getSheetByName(name);
    if (!sh || sh.getLastRow() < 2) return;
    sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues().forEach(function(r){
      var v = String(r[0] || '').trim();
      if (v) used[v.toLowerCase()] = true;
    });
  });
  var n = f.start, admNo, guard = 0;
  do {
    admNo = acsAdmBuild_(f, n);
    n++;
  } while (used[admNo.toLowerCase()] && ++guard < 1000000);
  return admNo;
}

/**
 * Scans Form1-4 + Students for AdmNo values used by more than one
 * student (a data problem that predates the unique-generation fix
 * above). Returns [{admNo, entries:[{name,className,sheet}]}].
 */
function findDuplicateAdmNos(){
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var byAdm = {};
  ['Form1','Form2','Form3','Form4','Students'].forEach(function(name){
    var sh = ss.getSheetByName(name);
    if (!sh || sh.getLastRow() < 2) return;
    var vals = sh.getDataRange().getValues();
    var header = vals[0].map(function(h){ return String(h||'').trim(); });
    var iAdm = header.indexOf('AdmNo'), iFirst = header.indexOf('FirstName'),
        iLast = header.indexOf('LastName'), iName = header.indexOf('Name'),
        iCls = header.indexOf('Class');
    if (iAdm < 0) iAdm = 0; // Form sheets always have AdmNo in col A
    vals.slice(1).forEach(function(r, idx){
      var admNo = String(r[iAdm] || '').trim();
      if (!admNo) return;
      var display = (iFirst > -1 || iLast > -1)
        ? ((r[iFirst] || '') + ' ' + (r[iLast] || '')).trim()
        : (iName > -1 ? String(r[iName] || '').trim() : '');
      var key = admNo.toLowerCase();
      if (!byAdm[key]) byAdm[key] = { admNo: admNo, entries: [] };
      byAdm[key].entries.push({
        name: display,
        className: iCls > -1 ? String(r[iCls] || '').trim() : name,
        sheet: name,
        row: idx + 2
      });
    });
  });
  return Object.keys(byAdm).map(function(k){ return byAdm[k]; })
    .filter(function(g){ return g.entries.length > 1; });
}

function saveStudent(data) {
  const ss      = SpreadsheetApp.getActiveSpreadsheet();
  const formNum = extractFormNumber(data.className);
  if (!formNum) return 'Error: Class must contain a number like "Form 1"';
  const sheetName = 'Form' + formNum;
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(['AdmNo','FirstName','LastName','Sex','DOB','Class','Parent','Phone','Address']);
    sheet.setFrozenRows(1);
    logActivity('system', 'Auto-created sheet: ' + sheetName);
  }
 let admNo = data.admNo;
  if (!admNo || admNo.trim() === '') {
    try { admNo = generateUniqueAdmNo(ss); } catch (e) { return 'Error: ' + e.message; }
  } else if (!data.oldId || data.oldId.trim() === '') {
    // Manually-typed AdmNo on a NEW student — reject if it collides with
    // an existing student anywhere (prevents the exact bug that let two
    // different students end up sharing the same AdmNo).
    var clash = getStudentListRaw().find(function(s){
      return String(s.admNo||'').trim().toLowerCase() === admNo.trim().toLowerCase();
    });
    if (clash) {
      return 'Error: Adm No. "' + admNo + '" is already used by ' + (clash.firstName||'') + ' ' + (clash.lastName||'') + ' (' + (clash.className||'') + '). Please use a different Adm No.';
    }
  }
  const row = [admNo, data.firstName, data.lastName, data.sex, data.dob,
               data.className, data.parent, data.phone, data.address];
  if (data.oldId && data.oldId.trim() !== '') {
    const vals = sheet.getDataRange().getValues();
    for (let i = 1; i < vals.length; i++) {
      if (vals[i][0] == data.oldId) {
        sheet.getRange(i+1, 1, 1, 9).setValues([row]);
        logActivity('academic', 'Updated student: ' + data.firstName + ' ' + data.lastName);
        return 'Student updated successfully in ' + data.className;
      }
    }
  }
  sheet.appendRow(row);
  logActivity('academic', 'Admitted: ' + data.firstName + ' ' + data.lastName + ' (' + admNo + ') to ' + sheetName);
  return 'Student ' + data.firstName + ' admitted to ' + data.className + ' successfully (' + admNo + ')';
}

function deleteStudent(admNo) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  // Students are actually saved into Form1-4 (see saveStudent), so look there first.
  const sheetNames = ['Form1', 'Form2', 'Form3', 'Form4', 'Students'];
  for (var s = 0; s < sheetNames.length; s++) {
    var sheet = ss.getSheetByName(sheetNames[s]);
    if (!sheet || sheet.getLastRow() < 2) continue;
    var data = sheet.getDataRange().getValues();
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][0]) == String(admNo)) { sheet.deleteRow(i + 1); return 'Student deleted'; }
    }
  }
  return 'Student not found';
}

